function renderDashboard() {
  const p=profile(), done=uniqueAttempted(p), total=questions().length, accuracy=correctRate(p), recent=p.attempts.slice().reverse().slice(0,4), modRows=MODULES.map(function(m){return progressRow(m.title,completedModule(p,m)+'% of in-app starter questions attempted',completedModule(p,m),'↗');}).join('');
  const lastUnique = new Set(p.attempts.map(function(a){return a.qid;})).size;
  const recommended = getWeakQuestions(p)[0] || QUESTIONS[0];
  const recentHTML=recent.length?recent.map(function(a){const q=getQuestion(a.qid);return '<div class="list-row"><div class="row-icon">'+(a.correct?'✓':'↻')+'</div><div class="row-main"><div class="row-title">'+esc(q.title)+'</div><div class="row-subtitle">'+esc(q.topic)+' · '+relativeDate(a.at)+'</div></div><span class="badge '+(a.correct?'green':'red')+'">'+(a.correct?'Correct':'Review')+'</span></div>';}).join(''):'<div class="empty-state"><div class="empty-icon">◷</div><h3>Your first attempt starts here</h3><p>Complete a practice question to begin building real performance analytics.</p><button class="btn small" data-action="nav" data-page="practice">Start practice ↗</button></div>';
  return '<div class="card hero-card"><div class="hero-copy"><div class="eyebrow">YOUR PERSONAL STUDY DESK</div><h2 class="hero-title">Understand the logic.<br>Own the valuation.</h2><p>Welcome, '+esc(state.activeProfile.split(' ')[0])+'. Work through the 2026 Equity Valuation curriculum with step-by-step solutions, original practice questions, a local source-book vault, and an independent progress record.</p><div class="hero-actions"><button class="btn" data-action="nav" data-page="practice">▶ Start a practice set</button><button class="btn secondary" data-action="nav" data-page="learn">Continue learning ↗</button></div></div><div class="hero-progress"><div class="ring" style="--ring-pct:'+pct(done,total)+'%"><div class="ring-inner"><div class="ring-number">'+pct(done,total)+'%</div><div class="ring-caption">attempted</div></div></div><div class="ring-label">'+done+' / '+total+' starter questions</div></div></div>' +
    '<div class="grid stats-grid">'+statCard('Unique questions attempted',done,'of '+total+' original in-app questions','◈')+statCard('Latest-answer accuracy',accuracy+'%','based on latest attempt per question','↗')+statCard('Study time logged',formatMin(studyMinutes(p)),'only time explicitly logged','◷')+statCard('Revision queue',getRevisionItems(p).length,'incorrect, bookmarked or not yet reviewed','↻')+'</div>' +
    '<div class="grid grid-2"><div class="card"><div class="card-header"><div><h3 class="card-title">Curriculum progress</h3><div class="card-subtitle">Six learning modules from your uploaded 2026 Equity Valuation volume.</div></div><button class="link-button" data-action="nav" data-page="curriculum">Explore curriculum ↗</button></div><div class="list">'+modRows+'</div></div><div class="card"><div class="card-header"><div><h3 class="card-title">Recommended next</h3><div class="card-subtitle">Prioritized from your current attempts and available practice.</div></div><span class="badge amber">Focus</span></div><div class="row-icon" style="width:44px;height:44px;font-size:18px;margin-bottom:14px">✳</div><h3 style="margin:0 0 7px;font:800 16px Manrope,sans-serif">'+esc(recommended.title)+'</h3><p class="section-subtitle" style="font-size:12px;margin-bottom:17px">'+esc(questionMeta(recommended))+'</p><div class="callout blue" style="margin-bottom:16px">The app contains original starter practice. The book’s full end-of-reading questions are not bundled into this public repository; import your own PDF locally in Source Import to work with its practice/solution pages.</div><button class="btn" data-action="open-question" data-qid="'+recommended.id+'">Practice this concept →</button></div></div>' +
    '<div class="grid grid-2" style="margin-top:17px"><div class="card"><div class="card-header"><div><h3 class="card-title">Recent attempts</h3><div class="card-subtitle">Your latest saved question results.</div></div><button class="link-button" data-action="nav" data-page="analytics">View analytics ↗</button></div><div class="list">'+recentHTML+'</div></div><div class="card"><div class="card-header"><div><h3 class="card-title">Study goal</h3><div class="card-subtitle">Set a daily target and log completed sessions in Profile & Settings.</div></div><span class="badge green">'+p.dailyGoal+' min/day</span></div><div style="font:800 26px Manrope,sans-serif;margin:9px 0 6px">'+formatMin(studyMinutes(p))+'</div><p class="section-subtitle" style="font-size:12px">Total manually logged study time; the app does not silently estimate time spent reading.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" data-action="log-study">Log a study session</button><button class="btn secondary" data-action="nav" data-page="settings">Adjust study goal →</button></div></div></div>' +
    '<div class="footer-note">Local-first prototype · Independent profiles on this browser · Not secure authentication or cross-device sync.</div>';
}
