  m.topics.map(function(t,i){return '<div class="topic-row"><div class="topic-summary" data-action="toggle-topic" data-topic-index="'+i+'"><div class="row-icon">0'+(i+1)+'</div><div class="topic-copy"><strong>'+esc(t.title)+'</strong><small>Printed page '+t.page+' · concept guide</small></div><span style="color:var(--accent)">＋</span></div><div class="topic-detail hidden" id="topic-'+i+'"><p>'+esc(t.body)+'</p><p><strong>Self-check:</strong> Can you state the key assumption, explain the economic intuition, and identify the input that would most change the conclusion?</p><button class="btn secondary small" data-action="nav" data-page="questions" data-module="'+m.id+'">Practice this module ↗</button></div></div>';}).join('')+
  '<div style="margin-top:17px"><button class="btn" data-action="nav" data-page="practice" data-module="'+m.id+'">Start module practice →</button> <button class="btn secondary" data-action="nav" data-page="source">Open source-page vault →</button></div>';
