  '<div class="card" style="margin-top:17px"><div class="card-header"><div><h3 class="card-title">Module-level detail</h3><div class="card-subtitle">Coverage means at least one saved attempt for a question currently available in that module.</div></div><button class="btn secondary small" data-action="export-data">Export my data</button></div><div class="table-wrap"><table><thead><tr><th>Learning module</th><th>Attempted</th><th>Question coverage</th><th>Latest accuracy</th><th>Next action</th></tr></thead><tbody>'+rows.map(function(r){return '<tr><td>LM '+r.m.no+' · '+esc(r.m.title)+'</td><td>'+r.answered+' / '+questions().filter(function(q){return q.module===r.m.id;}).length+'</td><td>'+r.covered+'%</td><td>'+(r.answered?r.acc+'%':'Not measured')+'</td><td><button class="link-button" data-action="study-module" data-module="'+r.m.id+'">Open module ↗</button></td></tr>';}).join('')+'</tbody></table></div></div>';
